package gpui

import (
	"runtime"
	"strings"
	"unicode/utf8"
)

const targetWindows = runtime.GOOS == "windows"

// AsKeystroke is implemented by values that carry a GPUI keystroke.
type AsKeystroke interface {
	// AsKeystroke returns the GPUI representation of the keystroke.
	AsKeystroke() *Keystroke
}

// Keystroke is a keystroke and associated metadata generated by the platform.
type Keystroke struct {
	// Modifiers is the state of the modifier keys at the time the keystroke was generated.
	Modifiers Modifiers `json:"modifiers"`
	// Key is the character printed on the key that was pressed, e.g. "s" for option-s.
	// On layouts without ASCII keys it is the ASCII-equivalent character.
	Key string `json:"key"`
	// KeyChar is the character that could have been typed when this binding was pressed:
	// "s" for s, "ß" for option-s, none for cmd-s.
	KeyChar Option[string] `json:"key_char"`
}

// KeybindingKeystroke is a keystroke that can be used in keybindings and displayed to the user.
type KeybindingKeystroke struct {
	inner            Keystroke
	displayModifiers Modifiers
	displayKey       string
}

// InvalidKeystrokeError is the error returned by KeystrokeParse.
type InvalidKeystrokeError struct {
	// Keystroke is the invalid keystroke.
	Keystroke string
}

// Error formats the error.
func (e *InvalidKeystrokeError) Error() string {
	return "Invalid keystroke \"" + e.Keystroke + "\". " + KeystrokeParseExpectedMessage
}

// KeystrokeParseExpectedMessage is the sentence explaining what the keystroke parser expects.
const KeystrokeParseExpectedMessage = "Expected a sequence of modifiers " +
	"(`ctrl`, `alt`, `shift`, `fn`, `cmd`, `super`, or `win`) " +
	"followed by a key, separated by `-`."

// ShouldMatch reports whether k, which was typed, matches target, which is in the keymap,
// either as the key_char or as the key itself.
func (k Keystroke) ShouldMatch(target KeybindingKeystroke) bool {
	return k.shouldMatch(target, targetWindows)
}

func (k Keystroke) shouldMatch(target KeybindingKeystroke, windows bool) bool {
	if keyChar, ok := k.KeyChar.Get(); ok && keyChar != k.Key {
		if !windows {
			imeModifiers := Modifiers{
				Control:  k.Modifiers.Control,
				Platform: k.Modifiers.Platform,
			}
			if target.inner.Key == keyChar && target.inner.Modifiers == imeModifiers {
				return true
			}
		} else if target.inner.Key == keyChar && target.inner.Modifiers == ModifiersNone() {
			return true
		}
	}
	return target.inner.Modifiers == k.Modifiers && target.inner.Key == k.Key
}

// KeystrokeParse parses a static keystroke with explicit, platform-independent modifiers.
//
// Syntax: `[ctrl-][alt-][shift-][cmd-][fn-]key[->key_char]`. Use KeystrokeParseWithOs for
// dynamic input or the `secondary-` alias.
func KeystrokeParse(source string) (Keystroke, error) {
	return keystrokeParseInternal(source, None[OperatingSystem]())
}

// KeystrokeParseWithOs parses a keystroke, resolving `secondary-` using the supplied host OS.
func KeystrokeParseWithOs(source string, os OperatingSystem) (Keystroke, error) {
	return keystrokeParseInternal(source, Some(os))
}

func asciiEqualFold(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := 0; i < len(a); i++ {
		if asciiLower(a[i]) != asciiLower(b[i]) {
			return false
		}
	}
	return true
}

func asciiLower(c byte) byte {
	if 'A' <= c && c <= 'Z' {
		return c + ('a' - 'A')
	}
	return c
}

func asciiToLower(s string) string {
	b := []byte(s)
	for i := range b {
		b[i] = asciiLower(b[i])
	}
	return string(b)
}

func keystrokeParseInternal(source string, os Option[OperatingSystem]) (Keystroke, error) {
	modifiers := ModifiersNone()
	var key Option[string]
	var keyChar Option[string]

	components := strings.Split(source, "-")
	for i := 0; i < len(components); i++ {
		component := components[i]
		if asciiEqualFold(component, "ctrl") {
			modifiers.Control = true
			continue
		}
		if asciiEqualFold(component, "alt") {
			modifiers.Alt = true
			continue
		}
		if asciiEqualFold(component, "shift") {
			modifiers.Shift = true
			continue
		}
		if asciiEqualFold(component, "fn") {
			modifiers.Function = true
			continue
		}
		if asciiEqualFold(component, "secondary") {
			hostOS, ok := os.Get()
			if !ok {
				return Keystroke{}, &InvalidKeystrokeError{Keystroke: source}
			}
			if hostOS == OperatingSystemMac {
				modifiers.Platform = true
			} else {
				modifiers.Control = true
			}
			continue
		}

		isPlatform := asciiEqualFold(component, "cmd") ||
			asciiEqualFold(component, "super") ||
			asciiEqualFold(component, "win")
		if isPlatform {
			modifiers.Platform = true
			continue
		}

		keyStr := component

		if i+1 < len(components) {
			next := components[i+1]
			if next == "" && strings.HasSuffix(source, "-") {
				key = Some("-")
				break
			} else if len(next) > 1 && strings.HasPrefix(next, ">") {
				key = Some(keyStr)
				keyChar = Some(next[1:])
				i++
			} else {
				return Keystroke{}, &InvalidKeystrokeError{Keystroke: source}
			}
			continue
		}

		if len(component) == 1 && 'A' <= component[0] && component[0] <= 'Z' {
			modifiers.Shift = true
			keyStr = asciiToLower(keyStr)
		} else {
			keyStr = asciiToLower(keyStr)
		}
		key = Some(keyStr)
	}

	if key.IsNone() {
		switch {
		case modifiers.Shift:
			modifiers.Shift = false
			key = Some("shift")
		case modifiers.Control:
			modifiers.Control = false
			key = Some("control")
		case modifiers.Alt:
			modifiers.Alt = false
			key = Some("alt")
		case modifiers.Platform:
			modifiers.Platform = false
			key = Some("platform")
		case modifiers.Function:
			modifiers.Function = false
			key = Some("function")
		}
	}

	k, ok := key.Get()
	if !ok {
		return Keystroke{}, &InvalidKeystrokeError{Keystroke: source}
	}
	return Keystroke{Modifiers: modifiers, Key: k, KeyChar: keyChar}, nil
}

// Unparse serializes the keystroke with the supplied host OS's modifier spelling.
func (k Keystroke) Unparse(os OperatingSystem) string {
	return unparse(k.Modifiers, k.Key, os)
}

// Display formats the keystroke using the supplied host OS's key labels.
func (k Keystroke) Display(os OperatingSystem) KeystrokeDisplay {
	return KeystrokeDisplay{modifiers: k.Modifiers, key: k.Key, os: os}
}

// IsIMEInProgress reports whether the keystroke left the IME system in an incomplete state.
func (k Keystroke) IsIMEInProgress() bool {
	return k.KeyChar.IsNone() &&
		(isPrintableKey(k.Key) || k.Key == "") &&
		!(k.Modifiers.Platform || k.Modifiers.Control || k.Modifiers.Function || k.Modifiers.Alt)
}

// WithSimulatedIME returns the keystroke with KeyChar filled, so dispatched keystrokes can
// simulate typing "space" and similar keys.
func (k Keystroke) WithSimulatedIME() Keystroke {
	if k.KeyChar.IsNone() &&
		!k.Modifiers.Platform &&
		!k.Modifiers.Control &&
		!k.Modifiers.Function &&
		!k.Modifiers.Alt {
		switch key := k.Key; {
		case key == "space":
			k.KeyChar = Some(" ")
		case key == "tab":
			k.KeyChar = Some("\t")
		case key == "enter":
			k.KeyChar = Some("\n")
		case !isPrintableKey(key) || key == "":
			k.KeyChar = None[string]()
		default:
			if k.Modifiers.Shift {
				k.KeyChar = Some(strings.ToUpper(key))
			} else {
				k.KeyChar = Some(key)
			}
		}
	}
	return k
}

// IsModifierKey reports whether the key itself is a modifier.
func (k Keystroke) IsModifierKey() bool {
	switch k.Key {
	case "shift", "control", "alt", "platform", "function":
		return true
	}
	return false
}

// AsKeystroke returns k.
func (k *Keystroke) AsKeystroke() *Keystroke {
	return k
}

// Display formats the binding using the supplied host OS's key labels.
func (k KeybindingKeystroke) Display(os OperatingSystem) KeystrokeDisplay {
	return KeystrokeDisplay{modifiers: k.Modifiers(), key: k.Key(), os: os}
}

// NewKeybindingKeystroke creates a keybinding keystroke with separate display modifiers and key
// (Windows; on other systems the display fields are not read).
func NewKeybindingKeystroke(inner Keystroke, displayModifiers Modifiers, displayKey string) KeybindingKeystroke {
	return KeybindingKeystroke{inner: inner, displayModifiers: displayModifiers, displayKey: displayKey}
}

// NewKeybindingKeystrokeWithMapper creates a keybinding keystroke from the keystroke using the keyboard mapper.
func NewKeybindingKeystrokeWithMapper(inner Keystroke, useKeyEquivalents bool, keyboardMapper PlatformKeyboardMapper) KeybindingKeystroke {
	return keyboardMapper.MapKeyEquivalent(inner, useKeyEquivalents)
}

// KeybindingKeystrokeFromKeystroke creates a keybinding keystroke without any platform-specific mapping.
func KeybindingKeystrokeFromKeystroke(keystroke Keystroke) KeybindingKeystroke {
	return keybindingKeystrokeFromKeystroke(keystroke, targetWindows)
}

func keybindingKeystrokeFromKeystroke(keystroke Keystroke, windows bool) KeybindingKeystroke {
	if windows {
		return KeybindingKeystroke{inner: keystroke, displayModifiers: keystroke.Modifiers, displayKey: keystroke.Key}
	}
	return KeybindingKeystroke{inner: keystroke}
}

// Inner returns the GPUI representation of the keystroke.
func (k *KeybindingKeystroke) Inner() *Keystroke {
	return &k.inner
}

// Modifiers returns the modifiers to display: the display modifiers on Windows, the
// keystroke's modifiers elsewhere.
func (k KeybindingKeystroke) Modifiers() Modifiers {
	return k.modifiers(targetWindows)
}

func (k KeybindingKeystroke) modifiers(windows bool) Modifiers {
	if windows {
		return k.displayModifiers
	}
	return k.inner.Modifiers
}

// Key returns the key to display: the display key on Windows, the keystroke's key elsewhere.
func (k KeybindingKeystroke) Key() string {
	return k.key(targetWindows)
}

func (k KeybindingKeystroke) key(windows bool) string {
	if windows {
		return k.displayKey
	}
	return k.inner.Key
}

// SetModifiers sets the modifiers; on Windows it also sets the display modifiers.
func (k *KeybindingKeystroke) SetModifiers(modifiers Modifiers) {
	k.inner.Modifiers = modifiers
	if targetWindows {
		k.displayModifiers = modifiers
	}
}

// SetKey sets the key; on Windows it also sets the display key.
func (k *KeybindingKeystroke) SetKey(key string) {
	if targetWindows {
		k.displayKey = key
	}
	k.inner.Key = key
}

// Unparse serializes the binding with the supplied host OS's modifier spelling.
func (k KeybindingKeystroke) Unparse(os OperatingSystem) string {
	return unparse(k.modifiers(targetWindows), k.key(targetWindows), os)
}

// RemoveKeyChar removes the key_char.
func (k *KeybindingKeystroke) RemoveKeyChar() {
	k.inner.KeyChar = None[string]()
}

// AsKeystroke returns the inner keystroke.
func (k *KeybindingKeystroke) AsKeystroke() *Keystroke {
	return &k.inner
}

func isPrintableKey(key string) bool {
	switch key {
	case "f1", "f2", "f3", "f4", "f5", "f6", "f7", "f8", "f9", "f10", "f11", "f12",
		"f13", "f14", "f15", "f16", "f17", "f18", "f19", "f20", "f21", "f22", "f23", "f24",
		"f25", "f26", "f27", "f28", "f29", "f30", "f31", "f32", "f33", "f34", "f35",
		"backspace", "delete", "left", "right", "up", "down", "pageup", "pagedown",
		"insert", "home", "end", "back", "forward", "escape":
		return false
	}
	return true
}

// KeystrokeDisplay is a keystroke formatted with an explicit host operating system.
type KeystrokeDisplay struct {
	modifiers Modifiers
	key       string
	os        OperatingSystem
}

// String formats the keystroke.
func (d KeystrokeDisplay) String() string {
	var b strings.Builder
	displayModifiers(d.modifiers, d.os, &b)
	displayKey(d.key, d.os, &b)
	return b.String()
}

// Modifiers is the state of the modifier keys at some point in time.
type Modifiers struct {
	// Control is the control key.
	Control bool `json:"control"`
	// Alt is the alt key, sometimes also known as the meta key.
	Alt bool `json:"alt"`
	// Shift is the shift key.
	Shift bool `json:"shift"`
	// Platform is the command key on macOS, the windows key on Windows, the super key on Linux.
	Platform bool `json:"platform"`
	// Function is the function key.
	Function bool `json:"function"`
}

// Modified reports whether any modifier key is pressed.
func (m Modifiers) Modified() bool {
	return m.Control || m.Alt || m.Shift || m.Platform || m.Function
}

// Secondary reports whether the semantically secondary modifier is pressed: command on macOS,
// control elsewhere.
func (m Modifiers) Secondary(cx *App) bool {
	if cx.PlatformInfo().IsMac() {
		return m.Platform
	}
	return m.Control
}

func b2u8(b bool) uint8 {
	if b {
		return 1
	}
	return 0
}

// NumberOfModifiers returns how many modifier keys are pressed.
func (m Modifiers) NumberOfModifiers() uint8 {
	return b2u8(m.Control) + b2u8(m.Alt) + b2u8(m.Shift) + b2u8(m.Platform) + b2u8(m.Function)
}

// ModifiersNone returns Modifiers with no modifiers.
func ModifiersNone() Modifiers {
	return Modifiers{}
}

// ModifiersCommand returns Modifiers with just the command key.
func ModifiersCommand() Modifiers {
	return Modifiers{Platform: true}
}

// ModifiersSecondaryKey returns Modifiers with just the secondary key pressed.
func ModifiersSecondaryKey(cx *App) Modifiers {
	if cx.PlatformInfo().IsMac() {
		return Modifiers{Platform: true}
	}
	return Modifiers{Control: true}
}

// ModifiersWindows returns Modifiers with just the windows key.
func ModifiersWindows() Modifiers {
	return Modifiers{Platform: true}
}

// ModifiersSuperKey returns Modifiers with just the super key.
func ModifiersSuperKey() Modifiers {
	return Modifiers{Platform: true}
}

// ModifiersControl returns Modifiers with just control.
func ModifiersControl() Modifiers {
	return Modifiers{Control: true}
}

// ModifiersAlt returns Modifiers with just alt.
func ModifiersAlt() Modifiers {
	return Modifiers{Alt: true}
}

// ModifiersShift returns Modifiers with just shift.
func ModifiersShift() Modifiers {
	return Modifiers{Shift: true}
}

// ModifiersFunction returns Modifiers with just function.
func ModifiersFunction() Modifiers {
	return Modifiers{Function: true}
}

// ModifiersCommandShift returns Modifiers with command and shift.
func ModifiersCommandShift() Modifiers {
	return Modifiers{Shift: true, Platform: true}
}

// ModifiersControlShift returns Modifiers with control and shift.
func ModifiersControlShift() Modifiers {
	return Modifiers{Shift: true, Control: true}
}

// IsSubsetOf reports whether m is a subset of other.
func (m Modifiers) IsSubsetOf(other Modifiers) bool {
	return other.BitAnd(m) == m
}

// BitOr returns the union of m and other.
func (m Modifiers) BitOr(other Modifiers) Modifiers {
	m.BitOrAssign(other)
	return m
}

// BitOrAssign sets every modifier of other in m.
func (m *Modifiers) BitOrAssign(other Modifiers) {
	m.Control = m.Control || other.Control
	m.Alt = m.Alt || other.Alt
	m.Shift = m.Shift || other.Shift
	m.Platform = m.Platform || other.Platform
	m.Function = m.Function || other.Function
}

// BitXor returns the symmetric difference of m and other.
func (m Modifiers) BitXor(other Modifiers) Modifiers {
	m.BitXorAssign(other)
	return m
}

// BitXorAssign toggles every modifier of other in m.
func (m *Modifiers) BitXorAssign(other Modifiers) {
	m.Control = m.Control != other.Control
	m.Alt = m.Alt != other.Alt
	m.Shift = m.Shift != other.Shift
	m.Platform = m.Platform != other.Platform
	m.Function = m.Function != other.Function
}

// BitAnd returns the intersection of m and other.
func (m Modifiers) BitAnd(other Modifiers) Modifiers {
	m.BitAndAssign(other)
	return m
}

// BitAndAssign clears every modifier of m that other lacks.
func (m *Modifiers) BitAndAssign(other Modifiers) {
	m.Control = m.Control && other.Control
	m.Alt = m.Alt && other.Alt
	m.Shift = m.Shift && other.Shift
	m.Platform = m.Platform && other.Platform
	m.Function = m.Function && other.Function
}

// Capslock is the state of the capslock key at some point in time.
type Capslock struct {
	// On reports whether capslock is on.
	On bool `json:"on"`
}

func displayModifiers(modifiers Modifiers, os OperatingSystem, f *strings.Builder) {
	if modifiers.Control {
		if os == OperatingSystemMac {
			f.WriteString("^")
		} else {
			f.WriteString("ctrl-")
		}
	}
	if modifiers.Alt {
		if os == OperatingSystemMac {
			f.WriteString("⌥")
		} else {
			f.WriteString("alt-")
		}
	}
	if modifiers.Platform {
		switch os {
		case OperatingSystemMac:
			f.WriteString("⌘")
		case OperatingSystemWindows:
			f.WriteString("⊞")
		case OperatingSystemLinux, OperatingSystemFreeBsd:
			f.WriteString("❖")
		default:
			f.WriteString("cmd-")
		}
	}
	if modifiers.Shift {
		if os == OperatingSystemMac {
			f.WriteString("⇧")
		} else {
			f.WriteString("shift-")
		}
	}
}

func displayKey(key string, os OperatingSystem, f *strings.Builder) {
	if os == OperatingSystemMac {
		var r rune
		switch key {
		case "backspace":
			r = '⌫'
		case "up":
			r = '↑'
		case "down":
			r = '↓'
		case "left":
			r = '←'
		case "right":
			r = '→'
		case "tab":
			r = '⇥'
		case "escape":
			r = '⎋'
		case "shift":
			r = '⇧'
		case "control":
			r = '⌃'
		case "alt":
			r = '⌥'
		case "platform":
			r = '⌘'
		}
		if r != 0 {
			f.WriteRune(r)
			return
		}
	}
	if len(key) == 1 {
		c, _ := utf8.DecodeRuneInString(key)
		if 'a' <= c && c <= 'z' {
			c -= 'a' - 'A'
		}
		f.WriteRune(c)
		return
	}
	f.WriteString(key)
}

func unparse(modifiers Modifiers, key string, os OperatingSystem) string {
	var result strings.Builder
	if modifiers.Function {
		result.WriteString("fn-")
	}
	if modifiers.Control {
		result.WriteString("ctrl-")
	}
	if modifiers.Alt {
		result.WriteString("alt-")
	}
	if modifiers.Platform {
		switch os {
		case OperatingSystemWindows:
			result.WriteString("win-")
		case OperatingSystemMac, OperatingSystemIos:
			result.WriteString("cmd-")
		default:
			result.WriteString("super-")
		}
	}
	if modifiers.Shift {
		result.WriteString("shift-")
	}
	result.WriteString(key)
	return result.String()
}
